PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    full_name TEXT NOT NULL,
    phone TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('ROLE_CUSTOMER', 'ROLE_PARTNER', 'ROLE_ADMIN')),
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, email_verified INTEGER NOT NULL DEFAULT 0, password_changed_at TEXT);
CREATE TABLE partners (
    id TEXT PRIMARY KEY,
    owner_user_id TEXT NOT NULL UNIQUE REFERENCES users(id),
    business_name TEXT NOT NULL,
    business_reg_number TEXT NOT NULL UNIQUE,
    commission_rate REAL NOT NULL DEFAULT 10.00,
    bank_code TEXT NOT NULL,
    bank_account_number TEXT NOT NULL,
    bank_account_holder TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'APPROVED' CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'SUSPENDED')),
    base_shipping_fee INTEGER NOT NULL DEFAULT 3000,
    free_shipping_threshold INTEGER NOT NULL DEFAULT 30000,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, settlement_cycle TEXT DEFAULT 'WEEKLY', return_shipping_address TEXT DEFAULT '인천광역시 중구 공항동 물류센터 B동 301호', customer_service_phone TEXT DEFAULT '1588-0000', partner_type TEXT DEFAULT 'DOMESTIC', country_code TEXT DEFAULT 'KR', kyc_status TEXT DEFAULT 'APPROVED', risk_tier TEXT DEFAULT 'TIER_1_NORMAL', rolling_reserve_pct REAL DEFAULT 0.0, settlement_currency TEXT DEFAULT 'KRW', swift_bic TEXT, payout_channel TEXT DEFAULT 'LOCAL_BANK', payout_account_id TEXT, representative_id_doc TEXT, business_cert_doc TEXT, tax_id_doc TEXT, kyc_notes TEXT);
CREATE TABLE categories (
    id TEXT PRIMARY KEY,
    parent_id TEXT REFERENCES categories(id),
    name TEXT NOT NULL,
    slug TEXT NOT NULL UNIQUE,
    depth INTEGER NOT NULL DEFAULT 0,
    sort_order INTEGER NOT NULL DEFAULT 0,
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE products (
    id TEXT PRIMARY KEY,
    partner_id TEXT NOT NULL REFERENCES partners(id),
    category_id TEXT NOT NULL REFERENCES categories(id),
    title TEXT NOT NULL,
    thumbnail_url TEXT NOT NULL,
    description_html TEXT NOT NULL,
    lowest_original_price INTEGER NOT NULL,
    lowest_sale_price INTEGER NOT NULL,
    total_sold_count INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('DRAFT', 'ACTIVE', 'HIDDEN', 'DELETED')),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, hs_code TEXT DEFAULT '6109.10', country_origin TEXT DEFAULT 'KR', package_length_cm REAL DEFAULT 20.0, package_width_cm REAL DEFAULT 15.0, package_height_cm REAL DEFAULT 10.0, package_weight_kg REAL DEFAULT 0.5, volumetric_weight_kg REAL DEFAULT 0.6, warehouse_location TEXT DEFAULT 'INCHEON_FBO', custody_type TEXT DEFAULT 'SEMI_MANAGED', supply_price INTEGER);
CREATE TABLE product_skus (
    id TEXT PRIMARY KEY,
    product_id TEXT NOT NULL REFERENCES products(id),
    sku_code TEXT NOT NULL UNIQUE,
    option_combination_json TEXT NOT NULL,
    original_price INTEGER NOT NULL,
    sale_price INTEGER NOT NULL,
    stock_quantity INTEGER NOT NULL DEFAULT 0,
    safety_stock INTEGER NOT NULL DEFAULT 5,
    status TEXT NOT NULL DEFAULT 'IN_STOCK' CHECK (status IN ('IN_STOCK', 'LOW_STOCK', 'OUT_OF_STOCK')),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE inventory_ledger (
    id TEXT PRIMARY KEY,
    sku_id TEXT NOT NULL REFERENCES product_skus(id),
    change_type TEXT NOT NULL CHECK (change_type IN ('PURCHASE_DEDUCT', 'RESTOCK', 'RETURN_RESTOCK', 'MANUAL_ADJUST', 'ORDER_CANCEL')),
    quantity_delta INTEGER NOT NULL,
    balance_after INTEGER NOT NULL,
    reference_id TEXT NOT NULL,
    idempotency_key TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE orders (
    id TEXT PRIMARY KEY,
    order_no TEXT NOT NULL UNIQUE,
    customer_id TEXT NOT NULL REFERENCES users(id),
    total_goods_amount INTEGER NOT NULL,
    total_shipping_amount INTEGER NOT NULL,
    total_discount_amount INTEGER NOT NULL DEFAULT 0,
    total_pay_amount INTEGER NOT NULL,
    currency TEXT NOT NULL DEFAULT 'KRW',
    payment_status TEXT NOT NULL DEFAULT 'PAID' CHECK (payment_status IN ('READY', 'PAID', 'FAILED', 'CANCELLED', 'PARTIAL_REFUNDED')),
    recipient_name TEXT NOT NULL,
    recipient_phone TEXT NOT NULL,
    shipping_address_line1 TEXT NOT NULL,
    shipping_address_line2 TEXT NOT NULL,
    shipping_postal_code TEXT NOT NULL,
    shipping_memo TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, pccc TEXT, pccc_verified INTEGER DEFAULT 0, customs_duty_type TEXT DEFAULT 'DDU', estimated_duty_amount INTEGER DEFAULT 0, settlement_currency TEXT DEFAULT 'KRW', fx_rate REAL DEFAULT 1.0, payment_key TEXT, pg_provider TEXT DEFAULT 'TOSS', pg_receipt_url TEXT);
CREATE TABLE sub_orders (
    id TEXT PRIMARY KEY,
    parent_order_id TEXT NOT NULL REFERENCES orders(id),
    sub_order_no TEXT NOT NULL UNIQUE,
    partner_id TEXT NOT NULL REFERENCES partners(id),
    shipping_fee INTEGER NOT NULL,
    goods_amount INTEGER NOT NULL,
    discount_amount INTEGER NOT NULL DEFAULT 0,
    total_amount INTEGER NOT NULL,
    status TEXT NOT NULL DEFAULT 'PAYMENT_CONFIRMED' CHECK (status IN ('PAYMENT_CONFIRMED', 'PREPARING', 'SHIPPED', 'DELIVERED', 'COMPLETED', 'CANCEL_REQUESTED', 'CANCELLED', 'RETURN_REQUESTED', 'RETURNED')),
    carrier_code TEXT,
    tracking_number TEXT,
    shipped_at TEXT,
    delivered_at TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, milestone_status TEXT DEFAULT 'PREPARING', flight_vessel_no TEXT, customs_clearance_no TEXT, origin_country TEXT DEFAULT 'KR', destination_country TEXT DEFAULT 'KR', last_milestone_location TEXT, last_milestone_updated_at TEXT, estimated_delivery_date TEXT, is_late_compensated INTEGER DEFAULT 0, late_compensation_amount INTEGER DEFAULT 0);
CREATE TABLE order_items (
    id TEXT PRIMARY KEY,
    sub_order_id TEXT NOT NULL REFERENCES sub_orders(id),
    sku_id TEXT NOT NULL REFERENCES product_skus(id),
    product_title TEXT NOT NULL,
    option_summary TEXT NOT NULL,
    unit_price INTEGER NOT NULL,
    quantity INTEGER NOT NULL,
    total_price INTEGER NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE settlements (
    id TEXT PRIMARY KEY,
    sub_order_id TEXT NOT NULL UNIQUE REFERENCES sub_orders(id),
    partner_id TEXT NOT NULL REFERENCES partners(id),
    gross_amount INTEGER NOT NULL,
    shipping_fee INTEGER NOT NULL,
    commission_rate REAL NOT NULL,
    commission_amount INTEGER NOT NULL,
    net_payout_amount INTEGER NOT NULL,
    status TEXT NOT NULL DEFAULT 'PENDING' CHECK (status IN ('HOLD', 'PENDING', 'SETTLED', 'CANCELLED')),
    settled_at TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE search_keywords (
    id TEXT PRIMARY KEY,
    keyword TEXT NOT NULL UNIQUE,
    normalized_keyword TEXT NOT NULL,
    chosung TEXT,
    category_id TEXT REFERENCES categories(id),
    category_name TEXT,
    category_slug TEXT,
    search_count INTEGER NOT NULL DEFAULT 1,
    product_hit_count INTEGER NOT NULL DEFAULT 0,
    is_promoted INTEGER NOT NULL DEFAULT 0,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE search_synonyms (
    id TEXT PRIMARY KEY,
    term TEXT NOT NULL,
    canonical_keyword TEXT NOT NULL,
    UNIQUE(term, canonical_keyword)
);
CREATE TABLE flash_sale_campaigns (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    banner_url TEXT,
    starts_at TEXT NOT NULL,
    ends_at TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('UPCOMING', 'ACTIVE', 'ENDED')),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE flash_sale_items (
    id TEXT PRIMARY KEY,
    campaign_id TEXT NOT NULL REFERENCES flash_sale_campaigns(id),
    product_id TEXT NOT NULL REFERENCES products(id),
    sku_id TEXT REFERENCES product_skus(id),
    deal_price INTEGER NOT NULL,
    discount_rate INTEGER NOT NULL,
    allocated_stock INTEGER NOT NULL,
    sold_stock INTEGER NOT NULL DEFAULT 0,
    sort_order INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE product_reviews (
    id TEXT PRIMARY KEY,
    product_id TEXT NOT NULL REFERENCES products(id),
    user_id TEXT NOT NULL REFERENCES users(id),
    reviewer_name TEXT NOT NULL,
    sku_option_summary TEXT,
    rating REAL NOT NULL CHECK(rating >= 1 AND rating <= 5),
    content TEXT NOT NULL,
    images_json TEXT DEFAULT '[]',
    helpful_count INTEGER NOT NULL DEFAULT 0,
    is_verified_purchase INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, order_id TEXT, author_name TEXT, user_height_cm INTEGER, user_weight_kg INTEGER, fit_type TEXT DEFAULT 'TRUE_TO_SIZE', photo_urls_json TEXT);
CREATE TABLE coupons (
    id TEXT PRIMARY KEY,
    code TEXT NOT NULL UNIQUE,
    title TEXT NOT NULL,
    discount_type TEXT NOT NULL CHECK(discount_type IN ('PERCENT', 'FIXED_AMOUNT')),
    discount_value INTEGER NOT NULL,
    min_order_amount INTEGER NOT NULL DEFAULT 0,
    max_discount_amount INTEGER,
    expires_at TEXT NOT NULL,
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_coupons (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    coupon_id TEXT NOT NULL REFERENCES coupons(id),
    is_used INTEGER NOT NULL DEFAULT 0,
    used_at TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_credits (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    amount_delta INTEGER NOT NULL,
    balance_after INTEGER NOT NULL,
    reason TEXT NOT NULL,
    reference_id TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE wishlists (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    product_id TEXT NOT NULL REFERENCES products(id),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_id, product_id)
);
CREATE TABLE returns (
    id TEXT PRIMARY KEY,
    order_id TEXT NOT NULL REFERENCES orders(id),
    user_id TEXT NOT NULL REFERENCES users(id),
    claim_type TEXT NOT NULL CHECK(claim_type IN ('RETURN', 'EXCHANGE', 'PRICE_ADJUSTMENT')),
    reason TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'REQUESTED' CHECK(status IN ('REQUESTED', 'APPROVED', 'REJECTED', 'REFUNDED')),
    refund_amount INTEGER NOT NULL DEFAULT 0,
    notes TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, is_returnless INTEGER DEFAULT 0, returnless_reason TEXT);
CREATE TABLE product_qna (
    id TEXT PRIMARY KEY,
    product_id TEXT NOT NULL REFERENCES products(id),
    partner_id TEXT NOT NULL REFERENCES partners(id),
    user_id TEXT NOT NULL REFERENCES users(id),
    questioner_name TEXT NOT NULL,
    question TEXT NOT NULL,
    answer TEXT,
    is_secret INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'WAITING' CHECK(status IN ('WAITING', 'ANSWERED')),
    answered_at TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE support_inquiries (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    order_id TEXT,
    category TEXT NOT NULL CHECK(category IN ('DELIVERY', 'REFUND_RETURN', 'PRICE_MATCH', 'PAYMENT', 'PARTNER_JOIN', 'OTHER')),
    subject TEXT NOT NULL,
    content TEXT NOT NULL,
    answer TEXT,
    status TEXT NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN', 'ANSWERED', 'CLOSED')),
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE user_addresses (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    recipient_name TEXT NOT NULL,
    phone TEXT NOT NULL,
    postal_code TEXT NOT NULL,
    address_line1 TEXT NOT NULL,
    address_line2 TEXT,
    is_default INTEGER NOT NULL DEFAULT 0,
    delivery_note TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE notifications (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id),
    title TEXT NOT NULL,
    message TEXT NOT NULL,
    type TEXT NOT NULL CHECK (type IN ('ORDER_STATUS', 'DISCOUNT', 'CREDIT_GRANTED', 'SYSTEM')),
    is_read INTEGER NOT NULL DEFAULT 0,
    action_url TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE banners (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    subtitle TEXT,
    badge_text TEXT,
    image_url TEXT NOT NULL,
    link_url TEXT NOT NULL,
    bg_gradient TEXT NOT NULL DEFAULT 'from-orange-500 to-red-600',
    display_order INTEGER NOT NULL DEFAULT 0,
    is_active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE password_reset_tokens (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  token TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  used_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE email_verification_tokens (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id),
  token TEXT NOT NULL UNIQUE,
  expires_at TEXT NOT NULL,
  verified_at TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE exchange_rates (
    base_currency TEXT NOT NULL DEFAULT 'KRW',
    target_currency TEXT NOT NULL,
    rate REAL NOT NULL,
    inverse_rate REAL NOT NULL,
    spread_pct REAL NOT NULL DEFAULT 1.2,
    updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (base_currency, target_currency)
);
CREATE TABLE milestone_tracking_logs (
    id TEXT PRIMARY KEY,
    sub_order_id TEXT NOT NULL REFERENCES sub_orders(id),
    carrier_code TEXT NOT NULL,
    tracking_number TEXT NOT NULL,
    stage_code TEXT NOT NULL,
    stage_name TEXT NOT NULL,
    location TEXT NOT NULL,
    description TEXT,
    occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE payment_transactions (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), payment_key TEXT UNIQUE, provider TEXT NOT NULL DEFAULT 'TOSS', method TEXT NOT NULL DEFAULT 'CARD', amount INTEGER NOT NULL, currency TEXT NOT NULL DEFAULT 'KRW', status TEXT NOT NULL DEFAULT 'DONE', receipt_url TEXT, raw_response_json TEXT, approved_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE storage_objects (id TEXT PRIMARY KEY, original_name TEXT NOT NULL, content_type TEXT NOT NULL, byte_size INTEGER NOT NULL, folder TEXT NOT NULL DEFAULT 'products', uploader_id TEXT, storage_backend TEXT NOT NULL DEFAULT 'D1_EMBEDDED', data_base64 TEXT, public_url TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notification_delivery_logs (id TEXT PRIMARY KEY, channel TEXT NOT NULL DEFAULT 'ALIMTALK', recipient TEXT NOT NULL, template_code TEXT NOT NULL, title TEXT, content TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'SENT', provider TEXT NOT NULL DEFAULT 'SOLAPI', provider_msg_id TEXT, sent_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sample_qc_requests (id TEXT PRIMARY KEY, partner_id TEXT NOT NULL REFERENCES partners(id), product_id TEXT, product_title TEXT NOT NULL, sample_tracking_no TEXT, carrier TEXT DEFAULT 'CJ대한통운', status TEXT NOT NULL DEFAULT 'PENDING', inspector_notes TEXT, inspected_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE partner_penalties (id TEXT PRIMARY KEY, partner_id TEXT NOT NULL REFERENCES partners(id), sub_order_id TEXT, penalty_type TEXT NOT NULL DEFAULT 'LATE_DISPATCH', penalty_amount INTEGER NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DEDUCTED', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ipr_takedown_reports (id TEXT PRIMARY KEY, reporter_name TEXT NOT NULL, brand_name TEXT NOT NULL, target_product_id TEXT NOT NULL REFERENCES products(id), infringement_type TEXT NOT NULL DEFAULT 'TRADEMARK', evidence_url TEXT, status TEXT NOT NULL DEFAULT 'SUBMITTED', admin_notes TEXT, processed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_search_kw_norm ON search_keywords(normalized_keyword);
CREATE INDEX idx_search_kw_chosung ON search_keywords(chosung);
CREATE INDEX idx_search_kw_count ON search_keywords(search_count DESC);
CREATE INDEX idx_prod_reviews_pid ON product_reviews(product_id);
CREATE INDEX idx_user_addresses_user_id ON user_addresses(user_id);
CREATE INDEX idx_notifications_user_id ON notifications(user_id);
