INSERT INTO "product_qna" ("id","product_id","partner_id","user_id","questioner_name","question","answer","is_secret","status","answered_at","created_at") VALUES('qna_002','prod_004','pt_001','u_customer_001','박*영','평소 100 사이즈 입는데 오버핏이면 M이 맞을까요 L이 맞을까요?','안녕하세요! 본 상품은 여유 있는 세미 오버핏으로 정사이즈 100 기준 자연스러운 핏은 M, 루즈한 오버핏은 L 사이즈를 추천드립니다.',0,'ANSWERED','2026-10-23 08:32:02','2026-10-22 08:32:02');
INSERT INTO "product_qna" ("id","product_id","partner_id","user_id","questioner_name","question","answer","is_secret","status","answered_at","created_at") VALUES('qna_003','prod_002','pt_002','u_customer_001','이*훈','220V 한국형 돼지코 플러그 기본 사양인가요?','네 고객님! KC 안전인증 완료된 국내 정식 규격 220V 플러그 일체형 제품으로 별도 어댑터 없이 바로 사용하실 수 있습니다.',0,'ANSWERED','2026-10-23 08:32:02','2026-10-23 08:32:02');
INSERT INTO "support_inquiries" ("id","user_id","order_id","category","subject","content","answer","status","created_at") VALUES('inq_001','u_customer_001',NULL,'PRICE_MATCH','30일 최저가 보상제 적립금 지급 기준 문의','구매 후 가격이 내려가면 언제든 신청 가능한가요?','네! 결제 완료일로부터 30일 이내 올모아 판매가가 인하된 경우 [주문 상세 > 최저가 차액 보상 신청] 버튼 클릭 시 차액 100%가 즉시 올모아 크레딧으로 자동 환급됩니다.','ANSWERED','2026-10-22 08:32:02');
